window.addEventListener('DOMContentLoaded',()=>{'use strict';
const $=id=>document.getElementById(id),flow=$('flow'),source=$('source'),cluster=$('cluster'),index=$('index');
const record={type:'object',properties:{id:{type:'string',minLength:1,maxLength:24},title:{type:'string',minLength:1,maxLength:32},category:{type:'string',enum:['FORM','MOTION','SIGNAL']}},required:['id','title','category'],additionalProperties:false},rows={type:'array',items:record,maxItems:24},envelope={type:'object',properties:{rows,total:{type:'integer',minimum:0,maximum:24}},required:['rows','total'],additionalProperties:false};
const titles=['Shell','Counterflow','Telemetry','Surface','Undulation','Packet','Topology','Orbit','Header','Lattice','Pulse','Signal'];const records=titles.map((title,i)=>({id:'r'+String(i+1).padStart(2,'0'),title,category:['FORM','MOTION','SIGNAL'][i%3]}));
const merge=(old,rows)=>Object.values(Object.fromEntries([...old,...rows].map(r=>[r.id,r]))).sort((a,b)=>a.id.localeCompare(b.id));
const glyphs=(list,layout,bounds)=>{const w=bounds.width,h=bounds.height,cx=w/2,cy=h*.57,R=Math.min(w*.31,h*.25);const marks=[];for(let i=0;i<180;i++){const v=1-2*(i+.5)/180,a=i*2.3999632297,r=Math.sqrt(1-v*v),t=i/179*Math.PI*6;const p=layout==='sphere'?{x:cx+R*r*Math.cos(a),y:cy+R*v,z:R*r*Math.sin(a)}:layout==='groups'?{x:w*(.14+(i%15)/14*.72),y:h*(.43+Math.floor(i/15)/11*.32),z:0}:{x:cx+R*.8*Math.cos(t),y:cy+(i/179-.5)*R*1.8,z:R*.8*Math.sin(t)};marks.push({id:'carrier'+i,...p,label:'+',color:layout==='groups'?'#2d4f3b':'#496e58'});}list.forEach((r,i)=>{const a=i/Math.max(list.length,1)*Math.PI*2;if(layout==='sphere'){marks.push({id:r.id,x:cx+R*Math.cos(a),y:cy+R*.55*Math.sin(a),z:R*.4*Math.sin(a),label:r.title.toUpperCase(),color:'#b7dfc1'});}else if(layout==='groups'){const group=['FORM','MOTION','SIGNAL'].indexOf(r.category),position=list.filter(x=>x.category===r.category).findIndex(x=>x.id===r.id);marks.push({id:r.id,x:w*(.22+group*.28),y:h*.47+position*17,z:0,label:r.title.toUpperCase(),color:['#d6dbad','#a8dbc2','#9ec7de'][group]});}else{marks.push({id:r.id,x:cx+R*.72*Math.cos(i*1.6),y:cy+(i-(list.length-1)/2)*11,z:R*.72*Math.sin(i*1.6),label:r.title.toUpperCase(),color:'#bcdac7'});}});if(layout==='groups')for(const [i,label] of ['FORM','MOTION','SIGNAL'].entries())marks.push({id:label,x:w*(.22+i*.28),y:h*.37,z:0,label,color:'#628572'});return marks;};
source.definition={input:rows,output:rows,initial:records,reduce:(_,input)=>input,organize:(state,b)=>glyphs(state,'sphere',b)};
cluster.definition={input:rows,output:envelope,initial:{FORM:[],MOTION:[],SIGNAL:[]},reduce:(state,input)=>{const all=merge(Object.values(state).flat(),input);return Object.fromEntries(['FORM','MOTION','SIGNAL'].map(k=>[k,all.filter(r=>r.category===k)]));},export:state=>{const all=Object.values(state).flat();return {rows:all,total:all.length};},organize:(state,b)=>glyphs(Object.values(state).flat(),'groups',b)};
index.definition={input:envelope,output:rows,initial:[],reduce:(state,input)=>{if(input.total!==input.rows.length)throw Error('Envelope total must equal rows.length.');return merge(state,input.rows);},organize:(state,b)=>glyphs(state,'helix',b)};
let batch=0,sequence=0,last=null;const status=$('status');function report(error){status.textContent=error.message;}
$('send').onclick=()=>{const selected=records.slice((batch%4)*3,(batch%4)*3+3);batch++;last='batch-'+(++sequence);source.send('cluster',selected,{id:last}).then(()=>status.textContent='Arrived. Category clusters received three records and arranged them by category.').catch(report);};
$('forward').onclick=()=>{last='index-'+(++sequence);cluster.send('index',cluster.export(),{id:last}).then(()=>status.textContent='Arrived. The index accepted { rows, total } and organized the content into its own helix.').catch(report);};
$('invalid').onclick=()=>source.send('cluster',[{id:'broken',title:'Wrong shape',category:42}]).then(()=>{throw Error('Invalid input was accepted.');}).catch(e=>status.textContent='Rejected before departure: '+e.message+' Receiver unchanged.');
$('pause').onclick=()=>{flow.toggleAttribute('paused');$('pause').textContent=flow.hasAttribute('paused')?'Resume':'Pause';};
$('drift').onchange=()=>{cluster.classList.toggle('drifter',$('drift').checked);};
$('reset').onclick=()=>{flow.reset();batch=0;sequence=0;last=null;status.textContent='Reset. All components are back to their initial content.';};
function update(){const state=flow.snapshot,groups=Object.values(cluster.value||{}).flat();$('cluster-count').textContent=groups.length+' received';$('index-count').textContent=index.value.length+' indexed';$('cluster-empty').hidden=groups.length>0;$('index-empty').hidden=index.value.length>0;$('forward').disabled=!groups.length;$('flight-count').textContent=state.flights.length+' IN FLIGHT';$('state').textContent=JSON.stringify({cluster:cluster.value,index:index.value,receipts:state.receipts},null,2);}
flow.addEventListener('glyph-state',update);flow.addEventListener('glyph-transfer',e=>{if(e.detail.status==='started')status.textContent='In transit. Content is copied; receiving state waits for arrival.';update();});flow.addEventListener('glyph-flow-error',e=>status.textContent=e.detail.message);update();
const barrier=$('barrier');let drag=null;function move(x,y){const r=flow.getBoundingClientRect();const clampedX=Math.max(0,Math.min(r.width-barrier.offsetWidth,x));barrier.style.left=clampedX+'px';barrier.style.top=Math.max(0,Math.min(r.height-barrier.offsetHeight,y))+'px';barrier.setAttribute('aria-valuenow',Math.round(100*clampedX/Math.max(1,r.width-barrier.offsetWidth)));}
barrier.onpointerdown=e=>{const a=barrier.getBoundingClientRect();drag={x:e.clientX-a.left,y:e.clientY-a.top};barrier.setPointerCapture(e.pointerId);};barrier.onpointermove=e=>{if(drag){const r=flow.getBoundingClientRect();move(e.clientX-r.left-drag.x,e.clientY-r.top-drag.y);}};barrier.onpointerup=barrier.onpointercancel=()=>drag=null;
barrier.setAttribute('aria-valuenow',Math.round(100*barrier.offsetLeft/Math.max(1,flow.clientWidth-barrier.offsetWidth)));
barrier.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const r=barrier.getBoundingClientRect(),s=flow.getBoundingClientRect(),d=e.shiftKey?24:6;move(r.left-s.left+(e.key==='ArrowRight'?d:e.key==='ArrowLeft'?-d:0),r.top-s.top+(e.key==='ArrowDown'?d:e.key==='ArrowUp'?-d:0));};
});
